SELECT * FROM schedule
WHERE doctor_id = #{doctorId}
  AND schedule_date >= #{startDate}
  AND schedule_date <= #{endDate}
  AND is_delete = 0
ORDER BY schedule_date, shift_type

SELECT * FROM schedule
WHERE department = #{department}
  AND schedule_date = #{scheduleDate}
  AND status = 1
  AND is_delete = 0
ORDER BY shift_type

SELECT * FROM schedule
WHERE schedule_date = #{scheduleDate}
  AND status = 1
  AND is_delete = 0

    AND shift_type = #{shiftType}

ORDER BY department, shift_type, doctor_name

SELECT COUNT(*) FROM schedule
WHERE doctor_id = #{doctorId}
  AND schedule_date = #{scheduleDate}
  AND shift_type = #{shiftType}
  AND is_delete = 0

mapper.update:
UPDATE schedule
SET current_appointments = current_appointments + #{delta}
WHERE id = #{id}
  AND is_delete = 0
